const translations = {"en":{"start":"Enter Your Sacred Space","instruction":"Choose your path or draw a single card","newReading":"Another Journey","readMeaning":"Seek Wisdom","share":"Divine Share","slots":{"past":"The Past","present":"The Present","future":"The Future","situation":"Current Situation","action":"Necessary Action","outcome":"Likely Outcome","card":"Sacred Guardian"},"spreads":{"single":"Single Gaze","three_ppf":"Timeline Spread","three_sao":"Insight Spread","celtic":"Ancient Cross (10)","horseshoe":"Horseshoe (7)"}},"es":{"start":"Comienza tu Viaje","instruction":"Elige una tirada o toca el mazo","newReading":"Nueva Lectura","readMeaning":"Ver Sabiduría","share":"Compartir Divino","slots":{"past":"El Pasado","present":"El Presente","future":"El Futuro","situation":"Situación Actual","action":"Acción Necesaria","outcome":"Resultado Probable"},"spreads":{"single":"Mirada Única","three_ppf":"Línea de Tiempo","three_sao":"Visión del Destino"}},"de":{"start":"Heiligen Raum betreten","instruction":"Wähle deinen Pfad oder ziehe eine Karte","newReading":"Neue Reise","readMeaning":"Weisheit suchen","share":"Göttliches Teilen"},"it":{"start":"Entra nello Spazio Sacro","instruction":"Scegli il tuo sentiero o pesca una carta","newReading":"Nuovo Viaggio","readMeaning":"Cerca Saggezza"},"fr":{"start":"Entrez dans l'Espace Sacré","instruction":"Choisissez votre voie ou tirez une carte","newReading":"Nouveau Voyage","readMeaning":"Chercher la Sagesse"}};
let currentLang = deckData.config.defaultLanguage || 'en';

// State
let drawnCards = [];

function updateUI() {
    document.querySelectorAll('[data-t]').forEach(el => {
        const key = el.getAttribute('data-t');
        const keys = key.split('.');
        let val = translations[currentLang] || translations['en'];
        for (const k of keys) val = val ? val[k] : null;
        if (val) el.textContent = val;
    });
}

function drawCard() {
    const card = deckData.cards[Math.floor(Math.random() * deckData.cards.length)];
    showInterpretation(card);
}

function showInterpretation(card) {
    const modal = document.getElementById('modal');
    const body = document.getElementById('modal-body');
    const title = card.title[currentLang] || card.title['en'];
    const meaning = card.meaning[currentLang] || card.meaning['en'];
    
    body.innerHTML = `
        <div class="reading-result">
            <img src="${card.image}" class="modal-card-img" style="width:100%; border-radius:1rem; margin-bottom:2rem; border:2px solid var(--amber)">
            <h2 style="color:var(--amber); margin-bottom:1rem">${title}</h2>
            <p style="line-height:1.6; opacity:0.8">${meaning.replace(/\n/g, '<br>')}</p>
        </div>
    `;
    modal.classList.remove('hidden');
}

document.getElementById('start-journey-btn').onclick = () => {
    document.getElementById('cover-screen').classList.add('hidden');
    document.getElementById('main-content').classList.remove('hidden');
};

document.getElementById('draw-trigger').onclick = drawCard;

document.getElementById('close-modal').onclick = () => {
    document.getElementById('modal').classList.add('hidden');
};

document.getElementById('lang-toggle').onclick = () => {
    document.getElementById('lang-dropdown').classList.toggle('hidden');
};

document.querySelectorAll('[data-lang]').forEach(btn => {
    btn.onclick = () => {
        currentLang = btn.getAttribute('data-lang');
        updateUI();
        document.getElementById('lang-dropdown').classList.add('hidden');
    };
});

updateUI();
